INSERT INTO subtitles (episode_id, index, start, "end", english, chinese, ipa, english_html)
SELECT e.id, 1, 0.0, 4.24, 'To be honest my main reason to go gym has been for aesthetic purposes.', '说实话，我去健身房的主要原因一直都是为了身材好看。', 'təbi ɑːnɪst maɪ meɪn ɹiːzən tə ɡoʊ dʒɪm hæzbiːn fɔːɹ ɛsθɛɾɪk pɜːpəsᵻz.', '<span pid="4101" class="highlight highlight-i">To be honest</span><span>my</span><span tid="151888">main</span><span tid="151889">reason</span><span>to</span><span>go</span><span tid="151892" class="highlight highlight-a">gym</span><span>has</span><span>been</span><span>for</span><span tid="151896" class="highlight highlight-a">aesthetic</span><span tid="151897">purposes.</span>'
