INSERT INTO subtitles (episode_id, index, start, "end", english, chinese, ipa, english_html)
SELECT e.id, 182, 759.04, 761.44, 'or a teacher, a coach, or a counselor.', '或者老师、教练，或者辅导员。', 'ɔːɹ ɐ tiːtʃɚ, ɐ koʊtʃ, ɔːɹ ɐ kaʊnsəlɚ.', '<span>or</span><span>a</span><span tid="159474">teacher,</span><span>a</span><span tid="159476" class="highlight highlight-a">coach,</span><span>or</span><span>a</span><span tid="159479">counselor.</span>'
