INSERT INTO subtitles (episode_id, index, start, "end", english, chinese, ipa, english_html)
SELECT e.id, 183, 761.88, 765.16, 'and ask them to help you stay on track to meet your goals.', '请他们帮助你保持在实现目标的正轨上。', 'ænd æsk ðɛm tə hɛlp juː steɪ ɔn tɹæk tə miːt jʊɹ ɡoʊlz.', '<span>and</span><span tid="159481">ask</span><span>them</span><span>to</span><span tid="159484">help</span><span>you</span><span pid="4286" class="highlight highlight-c">stay on track</span><span>to</span><span tid="159490">meet</span><span>your</span><span tid="159492">goals.</span>'
