INSERT INTO subtitles (episode_id, index, start, "end", english, chinese, ipa, english_html)
SELECT e.id, 184, 767.0, 769.68, 'And even when you''re struggling, even when you''re discouraged.', '即使你正在挣扎，即使你感到沮丧。', 'ænd iːvən wɛn jʊɹ stɹʌɡlɪŋ, iːvən wɛn jʊɹ dɪskɜːɹɪdʒd.', '<span>And</span><span tid="159494">even</span><span>when</span><span>you''re</span><span tid="159497">struggling,</span><span tid="159498">even</span><span>when</span><span>you''re</span><span tid="159501" class="highlight highlight-a">discouraged.</span>'
