INSERT INTO subtitles (episode_id, index, start, "end", english, chinese, ipa, english_html)
SELECT e.id, 185, 770.18, 776.02, 'and you feel like other people have given up on you, don''t ever give up on yourself.', '即使你觉得别人已经放弃了你，也永远不要放弃自己。', 'ænd juː fiːl laɪk ʌðɚ piːpəl hæv ɡɪvən ʌp ɔn juː, doʊnt ɛvɚ ɡɪv ʌp ɔn jɔːɹsɛlf.', '<span>and</span><span>you</span><span tid="159504">feel</span><span>like</span><span tid="159506">other</span><span tid="159507">people</span><span>have</span><span pid="4337" class="highlight highlight-d">given up on</span><span>you,</span><span>don''t</span><span tid="159514" class="highlight highlight-a">ever</span><span pid="4337" class="highlight highlight-d">give up on</span><span tid="159518">yourself.</span>'
