INSERT INTO subtitles (episode_id, index, start, "end", english, chinese, ipa, english_html)
SELECT e.id, 190, 793.16, 799.36, 'It''s the story of students who sat where you sit 250 years ago and went on to wage a revolution,', '这是那些两百五十年前坐在你们现在座位上的学生，后来发动革命的故事，', 'ɪts ðə stɔːɹi ʌv stuːdənts huː sæt wɛɹ juː sɪt tuːhʌndɹɪd fɪfti jɪɹz ɐɡoʊ ænd wɛnt ɔn tə weɪdʒ ɐ ɹɛvəluːʃən,', '<span>It''s</span><span>the</span><span tid="159569">story</span><span>of</span><span tid="159571">students</span><span>who</span><span tid="159573">sat</span><span>where</span><span>you</span><span tid="159576">sit</span><span>250</span><span>years</span><span tid="159579">ago</span><span>and</span><span>went</span><span>on</span><span>to</span><span tid="159584">wage</span><span>a</span><span tid="159586" class="highlight highlight-a">revolution,</span>'
