INSERT INTO subtitles (episode_id, index, start, "end", english, chinese, ipa, english_html)
SELECT e.id, 191, 799.6, 802.08, 'and they founded this nation, young people.', '也是他们创建这个国家的故事，年轻人。', 'ænd ðeɪ faʊndᵻd ðɪs neɪʃən, jʌŋ piːpəl.', '<span>and</span><span>they</span><span tid="159589">founded</span><span>this</span><span tid="159591">nation,</span><span tid="159592">young</span><span tid="159593">people.</span>'
