INSERT INTO subtitles (episode_id, index, start, "end", english, chinese, ipa, english_html)
SELECT e.id, 192, 803.32, 809.02, 'Students who sat where you sit 75 years ago who overcame a depression and won a world war,', '这是那些七十五年前坐在你们现在座位上的学生，战胜大萧条并赢得世界大战的故事，', 'stuːdənts huː sæt wɛɹ juː sɪt sɛvənti faɪv jɪɹz ɐɡoʊ huː oʊvɚkeɪm ɐ dᵻpɹɛʃən ænd wʌn ɐ wɜːld wɔːɹ,', '<span tid="159594">Students</span><span>who</span><span tid="159596">sat</span><span>where</span><span>you</span><span tid="159599">sit</span><span>75</span><span>years</span><span tid="159602">ago</span><span>who</span><span tid="159604" class="highlight highlight-a">overcame</span><span>a</span><span tid="159606" class="highlight highlight-a">depression</span><span>and</span><span tid="159608">won</span><span>a</span><span tid="159610">world</span><span tid="159611">war,</span>'
