INSERT INTO subtitles (episode_id, index, start, "end", english, chinese, ipa, english_html)
SELECT e.id, 193, 809.68, 812.32, 'who fought for civil rights and put a man on the moon.', '也是他们为民权而奋斗，并把人类送上月球的故事。', 'huː fɔːt fɔːɹ sɪvəl ɹaɪts ænd pʊt ɐ mæn ɔnðə muːn.', '<span>who</span><span tid="159613">fought</span><span>for</span><span pid="4339" class="highlight highlight-c">civil rights</span><span>and</span><span tid="159618">put</span><span>a</span><span tid="159620">man</span><span>on</span><span>the</span><span tid="159623" class="highlight highlight-a">moon.</span>'
