INSERT INTO subtitles (episode_id, index, start, "end", english, chinese, ipa, english_html)
SELECT e.id, 194, 813.28, 820.76, 'Students who sat where you sit 20 years ago who founded Google and Twitter and Facebook and changed the way we communicate with each other.', '这是那些二十年前坐在你们现在座位上的学生，创办了 Google、Twitter 和 Facebook，改变了我们彼此沟通方式的故事。', 'stuːdənts huː sæt wɛɹ juː sɪt twɛnti jɪɹz ɐɡoʊ huː faʊndᵻd ɡuːɡəl ænd twɪɾɚɹ ænd feɪsbʊk ænd tʃeɪndʒd ðə weɪ wiː kəmjuːnᵻkeɪt wɪð iːtʃ ʌðɚ.', '<span tid="159624">Students</span><span>who</span><span tid="159626">sat</span><span>where</span><span>you</span><span tid="159629">sit</span><span>20</span><span>years</span><span tid="159632">ago</span><span>who</span><span tid="159634">founded</span><span tid="159635">Google</span><span>and</span><span tid="159637">Twitter</span><span>and</span><span tid="159639">Facebook</span><span>and</span><span tid="159641">changed</span><span>the</span><span tid="159643" class="highlight highlight-a">way</span><span>we</span><span tid="159645">communicate</span><span>with</span><span tid="159647">each</span><span tid="159648">other.</span>'
