INSERT INTO subtitles (episode_id, index, start, "end", english, chinese, ipa, english_html)
SELECT e.id, 203, 865.0, 868.42, 'I expect you to put your best effort into everything you do.', '我期待你们在所做的每一件事上都付出最大的努力。', 'aɪ ɛkspɛkt juː tə pʊt jʊɹ bɛst ɛfɚt ɪntʊ ɛvɹɪθɪŋ juː duː.', '<span>I</span><span tid="159767">expect</span><span>you</span><span>to</span><span pid="4340" class="highlight highlight-c">put your best effort into</span><span>everything</span><span>you</span><span>do.</span>'
