INSERT INTO subtitles (episode_id, index, start, "end", english, chinese, ipa, english_html)
SELECT e.id, 1, 0.98, 6.26, 'I''m honored to be with you today for your commencement from one of the finest universities in the world.', '今天，我很荣幸能和各位在一起，参加你们从世界上最优秀的大学之一毕业的典礼。', 'aɪm ɑːnɚd təbi wɪð juː tədeɪ fɔːɹ jʊɹ kəmɛnsmənt fɹʌm wʌn ʌvðə faɪnɪst juːnɪvɜːsᵻɾiz ɪnðə wɜːld.', '<span>I''m</span><span tid="159825">honored</span><span>to</span><span>be</span><span>with</span><span>you</span><span tid="159830">today</span><span>for</span><span>your</span><span tid="159833">commencement</span><span>from</span><span>one</span><span>of</span><span>the</span><span tid="159838" class="highlight highlight-a">finest</span><span tid="159839">universities</span><span>in</span><span>the</span><span tid="159842">world.</span>'
