INSERT INTO subtitles (episode_id, index, start, "end", english, chinese, ipa, english_html)
SELECT e.id, 2, 9.8, 13.98, 'Truth be told, I never graduated from college.', '说实话，我从来没有大学毕业过。', 'tɹuːθ biː toʊld, aɪ nɛvɚ ɡɹædjuːeɪɾᵻd fɹʌm kɑːlɪdʒ.', '<span pid="4342" class="highlight highlight-c">Truth be told,</span><span>I</span><span tid="159847">never</span><span tid="159848" class="highlight highlight-a">graduated</span><span>from</span><span tid="159850">college.</span>'
FROM episodes e WHERE e.video_id = '164aQiyAcXRt7Np';
INSERT INTO subtitles (episode_id, index, start, "end", english, chinese, ipa, english_html)
SELECT e.id, 3, 15.16, 18.96, 'and this is the closest I''ve ever gotten to a college graduation.', '而今天，是我离大学毕业典礼最近的一次。', 'ænd ðɪs ɪz ðə kloʊsɪst aɪv ɛvɚ ɡɑːʔn̩ tʊ ɐ kɑːlɪdʒ ɡɹædʒuːeɪʃən.', '<span>and</span><span>this</span><span>is</span><span>the</span><span tid="159855">closest</span><span>I''ve</span><span tid="159857" class="highlight highlight-a">ever</span><span>gotten</span><span>to</span><span>a</span><span tid="159861">college</span><span tid="159862">graduation.</span>'
