INSERT INTO subtitles (episode_id, index, start, "end", english, chinese, ipa, english_html)
SELECT e.id, 4, 21.64, 24.5, 'Today, I want to tell you three stories from my life.', '今天，我想给你们讲三个我人生中的故事。', 'tədeɪ, aɪ wɔnt tə tɛl juː θɹiː stɔːɹiz fɹʌm maɪ laɪf.', '<span tid="159863">Today,</span><span>I</span><span>want</span><span>to</span><span tid="159867">tell</span><span>you</span><span>three</span><span tid="159870">stories</span><span>from</span><span>my</span><span tid="159873">life.</span>'
