INSERT INTO subtitles (episode_id, index, start, "end", english, chinese, ipa, english_html)
SELECT e.id, 5, 24.9, 26.54, 'That''s it. No big deal.', '就这些。没什么大道理。', 'ðætsɪt. noʊ bɪɡ diːl.', '<span>That''s</span><span>it.</span><span pid="4343" class="highlight highlight-c">No big deal.</span>'
