INSERT INTO subtitles (episode_id, index, start, "end", english, chinese, ipa, english_html)
SELECT e.id, 6, 26.94, 32.48, 'Just three stories. The first story is about connecting the dots.', '只是三个故事。第一个故事，是关于把生命中的点滴连接起来。', 'dʒʌst θɹiː stɔːɹiz. ðə fɜːst stɔːɹi ɪz ɐbaʊt kənɛktɪŋ ðə dɑːts.', '<span>Just</span><span>three</span><span tid="159881">stories.</span><span>The</span><span tid="159883">first</span><span tid="159884">story</span><span>is</span><span>about</span><span tid="159887">connecting</span><span>the</span><span tid="159889" class="highlight highlight-a">dots.</span>'
