INSERT INTO subtitles (episode_id, index, start, "end", english, chinese, ipa, english_html)
SELECT e.id, 54, 223.15, 224.37, 'and I found it fascinating.', '而我觉得它迷人极了。', 'ænd aɪ faʊnd ɪt fæsᵻneɪɾɪŋ.', '<span>and</span><span>I</span><span tid="160411">found</span><span>it</span><span tid="160413">fascinating.</span>'
