INSERT INTO subtitles (episode_id, index, start, "end", english, chinese, ipa, english_html)
SELECT e.id, 59, 239.59, 242.15, 'It was the first computer with beautiful typography.', '它成了第一台拥有漂亮字体排印的电脑。', 'ɪt wʌzðə fɜːst kəmpjuːɾɚ wɪð bjuːɾifəl taɪpɑːɡɹəfi.', '<span>It</span><span>was</span><span>the</span><span tid="160457">first</span><span tid="160458" class="highlight highlight-a">computer</span><span>with</span><span tid="160460">beautiful</span><span tid="160461" class="highlight highlight-a">typography.</span>'
