INSERT INTO subtitles (episode_id, index, start, "end", english, chinese, ipa, english_html)
SELECT e.id, 71, 294.61, 298.03, 'Because believing that the dots will connect down the road.', '因为相信这些点会在未来某一天连接起来，', 'bɪkʌz bᵻliːvɪŋ ðætðə dɑːts wɪl kənɛkt daʊn ðə ɹoʊd.', '<span>Because</span><span tid="160599">believing</span><span>that</span><span>the</span><span tid="160602" class="highlight highlight-a">dots</span><span>will</span><span tid="160604">connect</span><span>down</span><span>the</span><span tid="160607">road.</span>'
