INSERT INTO subtitles (episode_id, index, start, "end", english, chinese, ipa, english_html)
SELECT e.id, 126, 518.17, 521.27, 'My third story is about death.', '我的第三个故事，是关于死亡。', 'maɪ θɜːd stɔːɹi ɪz ɐbaʊt dɛθ.', '<span>My</span><span tid="161236">third</span><span tid="161237">story</span><span>is</span><span>about</span><span tid="161240">death.</span>'
FROM episodes e WHERE e.video_id = '164aQiyAcXRt7Np';
INSERT INTO subtitles (episode_id, index, start, "end", english, chinese, ipa, english_html)
SELECT e.id, 127, 522.49, 525.95, 'When I was 17, I read a quote that went something like,', '十七岁时，我读到过一句话，大意是：', 'wɛn aɪ wʌz sɛvəntiːn, aɪ ɹiːd ɐ kwoʊt ðæt wɛnt sʌmθɪŋ laɪk,', '<span>When</span><span>I</span><span>was</span><span>17,</span><span>I</span><span tid="161246">read</span><span>a</span><span tid="161248" class="highlight highlight-a">quote</span><span>that</span><span>went</span><span>something</span><span>like,</span>'
FROM episodes e WHERE e.video_id = '164aQiyAcXRt7Np';
INSERT INTO subtitles (episode_id, index, start, "end", english, chinese, ipa, english_html)
SELECT e.id, 128, 526.59, 528.91, 'If you live each day as if it was your last.', '如果你把每一天都当作生命中的最后一天来过，', 'ɪf juː lɪv iːtʃ deɪ æz ɪf ɪt wʌz jʊɹ læst.', '<span>If</span><span>you</span><span tid="161255">live</span><span tid="161256">each</span><span>day</span><span>as</span><span>if</span><span>it</span><span>was</span><span>your</span><span tid="161263" class="highlight highlight-a">last.</span>'
FROM episodes e WHERE e.video_id = '164aQiyAcXRt7Np';
INSERT INTO subtitles (episode_id, index, start, "end", english, chinese, ipa, english_html)
SELECT e.id, 129, 529.27, 531.19, 'someday you''ll most certainly be right.', '那么总有一天，你一定会是对的。', 'sʌmdeɪ juːl moʊst sɜːʔn̩li biː ɹaɪt.', '<span tid="161264">someday</span><span>you''ll</span><span tid="161266">most</span><span tid="161267" class="highlight highlight-a">certainly</span><span>be</span><span tid="161269" class="highlight highlight-a">right.</span>'
