INSERT INTO subtitles (episode_id, index, start, "end", english, chinese, ipa, english_html)
SELECT e.id, 132, 541.17, 546.61, 'if today were the last day of my life, would I want to do what I am about to do today?', '如果今天是我生命中的最后一天，我还会想去做今天将要做的事情吗？', 'ɪf tədeɪ wɜː ðə læst deɪ ʌv maɪ laɪf, wʊd aɪ wɔnt tə duː wʌt aɪɐm ɐbaʊt tə duː tədeɪ?', '<span>if</span><span tid="161295">today</span><span>were</span><span>the</span><span tid="161298" class="highlight highlight-a">last</span><span>day</span><span>of</span><span>my</span><span tid="161302">life,</span><span>would</span><span>I</span><span>want</span><span>to</span><span>do</span><span>what</span><span>I</span><span>am</span><span>about</span><span>to</span><span>do</span><span tid="161314">today?</span>'
