INSERT INTO subtitles (episode_id, index, start, "end", english, chinese, ipa, english_html)
SELECT e.id, 178, 717.63, 720.47, 'you will gradually become the old and be cleared away.', '你们也会逐渐变成旧的，然后被清除。', 'juː wɪl ɡɹædʒuːəli bɪkʌm ðɪ oʊld ænd biː klɪɹd ɐweɪ.', '<span>you</span><span>will</span><span tid="161787">gradually</span><span tid="161788">become</span><span>the</span><span>old</span><span>and</span><span>be</span><span tid="161793">cleared</span><span tid="161794">away.</span>'
FROM episodes e WHERE e.video_id = '164aQiyAcXRt7Np';
INSERT INTO subtitles (episode_id, index, start, "end", english, chinese, ipa, english_html)
SELECT e.id, 179, 721.19, 724.43, 'Sorry to be so dramatic, but it''s quite true.', '抱歉说得这么戏剧化，但这确实是真的。', 'sɑːɹi təbi soʊ dɹəmæɾɪk, bʌt ɪts kwaɪt tɹuː.', '<span tid="161795">Sorry</span><span>to</span><span>be</span><span>so</span><span tid="161799" class="highlight highlight-a">dramatic,</span><span>but</span><span>it''s</span><span tid="161802">quite</span><span tid="161803">true.</span>'
