INSERT INTO subtitles (episode_id, index, start, "end", english, chinese, ipa, english_html)
SELECT e.id, 44, 159.4, 163.64, 'after you take the action, do a reflection or an audit on that fear.', '在你采取行动之后，对这份恐惧做一次复盘或审计。', 'æftɚ juː teɪk ðɪ ækʃən, duː ɐ ɹᵻflɛkʃən ɔːɹ ɐn ɔːdɪt ɔn ðæt fɪɹ.', '<span tid="174228">after</span><span>you</span><span tid="174230">take</span><span>the</span><span tid="174232" class="highlight highlight-a">action,</span><span>do</span><span>a</span><span tid="174235" class="highlight highlight-a">reflection</span><span>or</span><span>an</span><span tid="174238" class="highlight highlight-a">audit</span><span>on</span><span>that</span><span tid="174241">fear.</span>'
