INSERT INTO subtitles (episode_id, index, start, "end", english, chinese, ipa, english_html)
SELECT e.id, 51, 182.24, 183.3, 'that it assigns fear.', '也就是它给恐惧贴上的那个意义。', 'ðɐɾɪt ɐsaɪnz fɪɹ.', '<span>that</span><span>it</span><span tid="174294" class="highlight highlight-a">assigns</span><span tid="174295">fear.</span>'
