INSERT INTO subtitles (episode_id, index, start, "end", english, chinese, ipa, english_html)
SELECT e.id, 57, 208.02, 213.58, 'from something that used to break you down into the single most potent indicator.', '它会从过去那个击垮你的东西，变成最有力的单一指标。', 'fɹʌm sʌmθɪŋ ðæt juːzd tə bɹeɪk juː daʊn ɪntʊ ðə sɪŋɡəl moʊst poʊtənt ɪndᵻkeɪɾɚ.', '<span>from</span><span>something</span><span>that</span><span tid="174366">used</span><span>to</span><span tid="174368">break</span><span>you</span><span>down</span><span tid="174371">into</span><span>the</span><span tid="174373" class="highlight highlight-a">single</span><span tid="174374">most</span><span tid="174375" class="highlight highlight-a">potent</span><span tid="174376" class="highlight highlight-a">indicator.</span>'
